<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\TenantConfigWelcomeEmailVO;

trait TenantConfigWelcomeEmailAttributeHolder
{
    protected TenantConfigWelcomeEmailVO|string|null $welcomeEmail = null;
    protected bool $welcomeEmailAssigned = false;

    public function getWelcomeEmailOrCurrent(?TenantConfigWelcomeEmailVO $welcomeEmail): ?TenantConfigWelcomeEmailVO
    {
        return $this->welcomeEmailAssigned ? ($this->welcomeEmail === null ? null : TenantConfigWelcomeEmailVO::from($this->welcomeEmail)) : $welcomeEmail;
    }
    public function welcomeEmailTryBuildInitial(ConstraintFailList $error): ?TenantConfigWelcomeEmailVO
    {
        return  TenantConfigWelcomeEmailVO::tryFrom($this->welcomeEmailAssigned ? $this->welcomeEmail : null, $error);
    }
    public function welcomeEmail(TenantConfigWelcomeEmailVO|string|null $welcomeEmail): static
    {
        $this->welcomeEmail = $welcomeEmail;
        $this->welcomeEmailAssigned = true;
        return $this;
    }
    public function getWelcomeEmail(): ?string
    {
        return $this->welcomeEmail instanceof TenantConfigWelcomeEmailVO ? $this->welcomeEmail->value() : $this->welcomeEmail;
    }
    public function isWelcomeEmailAssigned(): bool
    {
        return $this->welcomeEmailAssigned;
    }
    public function writeWelcomeEmailTo(mixed $att): void
    {
        if ($this->welcomeEmailAssigned) {
            $att->welcomeEmail($this->welcomeEmail);
        }
    }
    public function readWelcomeEmailFrom(mixed $att): void
    {
        if ($att->isWelcomeEmailAssigned()) {
            $welcomeEmail = $att->getWelcomeEmail();
            $this->welcomeEmail($welcomeEmail);
        }
    }
    public function unsetWelcomeEmail(): static
    {
        $this->welcomeEmailAssigned = false;
        return $this;
    }
    protected function withDefaultWelcomeEmail(): void
    {
    }
    protected function withAssertedWelcomeEmailRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->welcomeEmailAssigned = $this->welcomeEmailAssigned) {
            $value->welcomeEmail = TenantConfigWelcomeEmailVO::tryFrom($this->welcomeEmail, $errorsList);
        }
    }
}
